from statsmodels.stats.multitest import multipletests
import statsmodels.stats.multitest as _multitest

# Names expected by the expressions
multitest_methods_names = list(getattr(_multitest, 'multipletests_methods', {}).keys())
# [record name, expression, bindings the report attached, reported expected text]
__numagent_cases__ = [["multipletests([], method=method) for each method in sorted(multitest_methods_names)", "multipletests([], method=method) for each method in sorted(multitest_methods_names)", [], "returns (reject, pvals_corrected, alphac_sidak, alphac_bonf) with reject.shape == (0,), pvals_corrected.shape == (0,), np.isnan(alphac_sidak) is True, np.isnan(alphac_bonf) is True"]]
for __numagent_name, __numagent_expr, __numagent_binds, __numagent_want in __numagent_cases__:
    try:
        for __numagent_bind in __numagent_binds:
            exec(__numagent_bind)
        probe(__numagent_name, eval(__numagent_expr))
    except Exception as __numagent_err:
        probe(__numagent_name, "__error__: " + type(__numagent_err).__name__
              + ": " + str(__numagent_err)[:200])
    if __numagent_want:
        try:    # the expectation may itself be an expression in this language
            probe("expected::" + __numagent_name, eval(__numagent_want))
        except Exception:
            pass                    # prose, not code — the comparator handles it

